def investigate(context, acquire):
    table = {}
    high = 0
    open_transaction = False
    pending = None
    for action in context['actions']:
        op = action['op']
        if op == 'begin':
            open_transaction = True
            pending = dict(table)
        elif op == 'commit':
            open_transaction = False
            pending = None
        elif op == 'rollback':
            open_transaction = False
            table = pending
            high = max(table) if table else 0
            pending = None
        elif op == 'put':
            ident = action['id']
            table[ident] = True
            if ident > high:
                high = ident
        elif op == 'delete':
            ident = action['id']
            if ident in table:
                del table[ident]
    return high + 1

