def investigate(context, acquire):
    seen = set()
    for row in context.get('examples', []):
        item = row.get('input') if isinstance(row, dict) else None
        if isinstance(item, dict):
            seen.add(repr(item))
    for row in context.get('receipts', []):
        item = row.get('query') if isinstance(row, dict) else None
        if isinstance(item, dict):
            seen.add(repr(item))
    candidates = [
        {'actions': [{'op': 'put', 'id': 1000}]},
        {'actions': [{'op': 'begin'}, {'op': 'put', 'id': 1000}, {'op': 'commit'}]},
        {'actions': [{'op': 'put', 'id': 1}, {'op': 'begin'}, {'op': 'delete', 'id': 1}, {'op': 'rollback'}]},
        {'actions': [{'op': 'put', 'id': 1}, {'op': 'begin'}, {'op': 'delete', 'id': 1}, {'op': 'commit'}]},
        {'actions': [{'op': 'begin'}, {'op': 'put', 'id': 5}, {'op': 'delete', 'id': 5}, {'op': 'commit'}]},
        {'actions': [{'op': 'put', 'id': 999}, {'op': 'put', 'id': 1000}]},
        {'actions': [{'op': 'put', 'id': 1}, {'op': 'delete', 'id': 1}, {'op': 'begin'}, {'op': 'put', 'id': 2}, {'op': 'rollback'}]},
        {'actions': [{'op': 'begin'}, {'op': 'put', 'id': 1}, {'op': 'begin'}]}
    ]
    for candidate in candidates:
        if repr(candidate) not in seen:
            return {'query': candidate, 'note': {'focus': 'AUTOINCREMENT sqlite_sequence persistence across commit/rollback and upper ID boundary'}}
    return {'query': None, 'note': {'focus': 'all candidate queries already exercised'}}

