def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    high = 0
    live = set()
    tx_high = 0
    tx_live = set()
    tx_deleted = set()
    open_tx = False
    for action in actions:
        op = action.get('op')
        if op == 'put':
            ident = action.get('id')
            if open_tx:
                if ident in tx_live or ident in tx_deleted:
                    return None
                tx_live.add(ident)
                tx_deleted.discard(ident)
                if ident > tx_high:
                    tx_high = ident
            else:
                if ident in live:
                    return None
                live.add(ident)
                if ident > high:
                    high = ident
        elif op == 'delete':
            ident = action.get('id')
            if open_tx:
                if ident in tx_live:
                    tx_live.remove(ident)
                    tx_deleted.add(ident)
                elif ident in live:
                    tx_deleted.add(ident)
            else:
                live.discard(ident)
        elif op == 'begin':
            if open_tx:
                return None
            open_tx = True
            tx_high = high
            tx_live = set(live)
            tx_deleted = set()
        elif op == 'commit':
            if not open_tx:
                return None
            high = tx_high
            live = set(tx_live)
            open_tx = False
            tx_high = 0
            tx_live = set()
            tx_deleted = set()
        elif op == 'rollback':
            if not open_tx:
                return None
            open_tx = False
            tx_high = 0
            tx_live = set()
            tx_deleted = set()
    return high + 1

